wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(235182401994267621)
,p_plug_name=>'Total'
,p_parent_plug_id=>wwv_flow_imp.id(238777429585480033)
,p_region_template_options=>'#DEFAULT#:t-CardsRegion--hideHeader js-addHiddenHeadingRoleDesc:t-CardsRegion--styleC:t-Region-orderBy--center'
,p_plug_template=>2072724515482255512
,p_plug_display_sequence=>20
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'  1 AS card_primary_key,',
'  ''Total Income'' AS card_title,',
'  ''All income transactions'' AS card_subtitle,',
'  TO_CHAR(NVL(SUM(CASE WHEN t.code=''INCOME'' THEN tr.amount ELSE 0 END),0)) AS card_body,',
'  ''This month'' AS card_secondary_body,',
'  ''fa-badge-dollar fa'' AS card_icon,',
'  COUNT(*) AS card_badge,',
'  NULL AS card_image',
'FROM transactions tr JOIN txn_types t ON tr.type_id = t.id',
'WHERE tr.added_by = :APP_USER AND t.code=''INCOME''',
'',
'UNION ALL',
'',
'SELECT ',
'  2, ''Total Expense'', ''All expense transactions'',',
'  TO_CHAR(NVL(SUM(CASE WHEN t.code=''EXPENSE'' THEN tr.amount ELSE 0 END),0)),',
'  ''This month'', ''fa-credit-card fa'', COUNT(*), NULL',
'FROM transactions tr JOIN txn_types t ON tr.type_id = t.id',
'WHERE tr.added_by = :APP_USER AND t.code=''EXPENSE''',
'',
'UNION ALL',
'',
'SELECT ',
'  3, ''Total Deposit'', ''All deposit transactions'',',
'  TO_CHAR(NVL(SUM(CASE WHEN t.code=''DEPOSIT'' THEN tr.amount ELSE 0 END),0)),',
'  ''This month'', ''fa-piggy-bank fa'', COUNT(*), NULL',
'FROM transactions tr JOIN txn_types t ON tr.type_id = t.id',
'WHERE tr.added_by = :APP_USER AND t.code=''DEPOSIT''',
'',
'UNION ALL',
'',
'SELECT ',
'  4, ''Net Balance'', ''Income minus Expense'',',
'  TO_CHAR(NVL(SUM(CASE WHEN t.code=''INCOME'' THEN tr.amount ELSE 0 END),0) -',
'          NVL(SUM(CASE WHEN t.code=''EXPENSE'' THEN tr.amount ELSE 0 END),0)),',
'  ''This month'', ''fa-line-chart fa'', NULL, NULL',
'FROM transactions tr JOIN txn_types t ON tr.type_id = t.id',
'WHERE tr.added_by = :APP_USER;',
''))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_plug_query_num_rows_type=>'SCROLL'
,p_show_total_row_count=>false
);
