,p_parent_plug_id=>wwv_flow_imp.id(238777548912480034)
,p_region_template_options=>'#DEFAULT#:t-CardsRegion--styleC:t-Region-orderBy--center'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>2072724515482255512
,p_plug_display_sequence=>30
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'  1 AS card_primary_key,',
'  TO_CHAR(SYSDATE,''Month'') || '' Income'' AS card_title,',
'  ''All income transactions'' AS card_subtitle,',
'  TO_CHAR(NVL(SUM(CASE WHEN t.code=''INCOME'' THEN tr.amount ELSE 0 END),0)) AS card_body,',
'  TO_CHAR(SYSDATE,''Month'') AS card_secondary_body,',
'  ''fa-badge-dollar fa'' AS card_icon,',
'  COUNT(*) AS card_badge,',
'  NULL AS card_image',
'FROM transactions tr JOIN txn_types t ON tr.type_id = t.id',
'WHERE tr.added_by = :APP_USER ',
'  AND t.code=''INCOME''',
'  AND TRUNC(tr.txn_date,''MM'') = TRUNC(SYSDATE,''MM'')',
'',
'UNION ALL',
'',
'SELECT ',
'  2, TO_CHAR(SYSDATE,''Month'') || '' Expense'', ''All expense transactions'',',
'  TO_CHAR(NVL(SUM(CASE WHEN t.code=''EXPENSE'' THEN tr.amount ELSE 0 END),0)),',
'  TO_CHAR(SYSDATE,''Month''), ''fa-credit-card fa'', COUNT(*), NULL',
'FROM transactions tr JOIN txn_types t ON tr.type_id = t.id',
'WHERE tr.added_by = :APP_USER ',
'  AND t.code=''EXPENSE''',
'  AND TRUNC(tr.txn_date,''MM'') = TRUNC(SYSDATE,''MM'')',
'',
'UNION ALL',
'',
'SELECT ',
'  3, TO_CHAR(SYSDATE,''Month'') || '' Deposit'', ''All deposit transactions'',',
'  TO_CHAR(NVL(SUM(CASE WHEN t.code=''DEPOSIT'' THEN tr.amount ELSE 0 END),0)),',
'  TO_CHAR(SYSDATE,''Month''), ''fa-piggy-bank fa'', COUNT(*), NULL',
'FROM transactions tr JOIN txn_types t ON tr.type_id = t.id',
'WHERE tr.added_by = :APP_USER ',
'  AND t.code=''DEPOSIT''',
'  AND TRUNC(tr.txn_date,''MM'') = TRUNC(SYSDATE,''MM'')',
'',
'UNION ALL',
'',
'SELECT ',
'  4, TO_CHAR(SYSDATE,''Month'') || '' Net Balance'', ''Income minus Expense'',',
'  TO_CHAR(NVL(SUM(CASE WHEN t.code=''INCOME'' THEN tr.amount ELSE 0 END),0) -',
'          NVL(SUM(CASE WHEN t.code=''EXPENSE'' THEN tr.amount ELSE 0 END),0)),',
'  TO_CHAR(SYSDATE,''Month''), ''fa-line-chart fa'', NULL, NULL',
'FROM transactions tr JOIN txn_types t ON tr.type_id = t.id',
'WHERE tr.added_by = :APP_USER',
'  AND TRUNC(tr.txn_date,''MM'') = TRUNC(SYSDATE,''MM'');',
''))
