,p_plug_template=>2072724515482255512
,p_plug_display_sequence=>40
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'  1 AS card_primary_key,',
'  TO_CHAR(ADD_MONTHS(SYSDATE,-1),''Month'') || '' Income'' AS card_title,',
'  ''All income Previous month transactions'' AS card_subtitle,',
'  TO_CHAR(NVL(SUM(CASE WHEN t.code=''INCOME'' THEN tr.amount ELSE 0 END),0)) AS card_body,',
'  TO_CHAR(ADD_MONTHS(SYSDATE,-1),''Month'') AS card_secondary_body,',
'  ''fa-badge-dollar fa'' AS card_icon,',
'  COUNT(*) AS card_badge,',
'  NULL AS card_image',
'FROM transactions tr JOIN txn_types t ON tr.type_id = t.id',
'WHERE tr.added_by = :APP_USER ',
'  AND t.code=''INCOME''',
'  AND TRUNC(tr.txn_date,''MM'') = ADD_MONTHS(TRUNC(SYSDATE,''MM''),-1)',
'',
'UNION ALL',
'',
'SELECT ',
'  2, TO_CHAR(ADD_MONTHS(SYSDATE,-1),''Month'') || '' Expense'', ''All expense Previous month transactions'',',
'  TO_CHAR(NVL(SUM(CASE WHEN t.code=''EXPENSE'' THEN tr.amount ELSE 0 END),0)),',
'  TO_CHAR(ADD_MONTHS(SYSDATE,-1),''Month''), ''fa-credit-card fa'', COUNT(*), NULL',
'FROM transactions tr JOIN txn_types t ON tr.type_id = t.id',
'WHERE tr.added_by = :APP_USER ',
'  AND t.code=''EXPENSE''',
'  AND TRUNC(tr.txn_date,''MM'') = ADD_MONTHS(TRUNC(SYSDATE,''MM''),-1)',
'',
'UNION ALL',
'',
'SELECT ',
'  3, TO_CHAR(ADD_MONTHS(SYSDATE,-1),''Month'') || '' Deposit'', ''All deposit Previous month transactions'',',
'  TO_CHAR(NVL(SUM(CASE WHEN t.code=''DEPOSIT'' THEN tr.amount ELSE 0 END),0)),',
'  TO_CHAR(ADD_MONTHS(SYSDATE,-1),''Month''), ''fa-piggy-bank fa'', COUNT(*), NULL',
'FROM transactions tr JOIN txn_types t ON tr.type_id = t.id',
'WHERE tr.added_by = :APP_USER ',
'  AND t.code=''DEPOSIT''',
'  AND TRUNC(tr.txn_date,''MM'') = ADD_MONTHS(TRUNC(SYSDATE,''MM''),-1)',
'',
'UNION ALL',
'',
'SELECT ',
'  4, TO_CHAR(ADD_MONTHS(SYSDATE,-1),''Month'') || '' Net Balance'', ''Income minus Expense Previous month'',',
'  TO_CHAR(NVL(SUM(CASE WHEN t.code=''INCOME'' THEN tr.amount ELSE 0 END),0) -',
'          NVL(SUM(CASE WHEN t.code=''EXPENSE'' THEN tr.amount ELSE 0 END),0)),',
'  TO_CHAR(ADD_MONTHS(SYSDATE,-1),''Month''), ''fa-line-chart fa'', NULL, NULL',
'FROM transactions tr JOIN txn_types t ON tr.type_id = t.id',
'WHERE tr.added_by = :APP_USER',
'  AND TRUNC(tr.txn_date,''MM'') = ADD_MONTHS(TRUNC(SYSDATE,''MM''),-1);',
''))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_plug_query_num_rows_type=>'SCROLL'
,p_show_total_row_count=>false
);
