wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(238775408309480013)
,p_plug_name=>'Summary Reports'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>2100526641005906379
,p_plug_display_sequence=>20
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    TO_CHAR(tr.txn_date, ''Month-YYYY'') AS month_name,',
'    SUM(CASE WHEN t.code = ''INCOME''  THEN tr.amount ELSE 0 END) AS income,',
'    SUM(CASE WHEN t.code = ''EXPENSE'' THEN tr.amount ELSE 0 END) AS expense,',
'    SUM(CASE WHEN t.code = ''DEPOSIT'' THEN tr.amount ELSE 0 END) AS deposit,',
'    SUM(CASE WHEN t.code = ''INCOME''  THEN tr.amount ELSE 0 END) -',
'    SUM(CASE WHEN t.code = ''EXPENSE'' THEN tr.amount ELSE 0 END) AS net_balance,',
'    SUM(SUM(CASE WHEN t.code = ''INCOME''  THEN tr.amount ELSE 0 END) -',
'        SUM(CASE WHEN t.code = ''EXPENSE'' THEN tr.amount ELSE 0 END))',
'        OVER (ORDER BY TO_CHAR(tr.txn_date,''YYYY-MM'')) AS cumulative_balance',
'FROM transactions tr',
'JOIN txn_types t ON tr.type_id = t.id',
'WHERE tr.added_by = :APP_USER',
'GROUP BY TO_CHAR(tr.txn_date, ''Month-YYYY''), TO_CHAR(tr.txn_date,''YYYY-MM'')',
'ORDER BY TO_CHAR(tr.txn_date,''YYYY-MM'');',
''))
