,p_plug_name=>'Category Report'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>2100526641005906379
,p_plug_display_sequence=>50
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    TO_CHAR(TRUNC(tr.txn_date),''DD-Mon-YYYY'') AS day_name,   -- formatted day',
'    c.name AS category,',
'    SUM(tr.amount) AS amount,',
'    SUM(SUM(tr.amount)) ',
'        OVER (',
'            PARTITION BY c.name ',
'            ORDER BY TRUNC(tr.txn_date)',
'            ROWS UNBOUNDED PRECEDING',
'        ) AS cumulative_total',
'FROM transactions tr',
'JOIN txn_types t ON tr.type_id = t.id',
'JOIN categories c ON tr.category_id = c.id',
'WHERE tr.added_by = :APP_USER',
'  AND tr.txn_date BETWEEN ',
'        NVL(:P25_START_DATE, TRUNC(SYSDATE,''MM'')) ',
'    AND NVL(:P25_END_DATE, LAST_DAY(SYSDATE))',
'GROUP BY TRUNC(tr.txn_date), c.name',
'ORDER BY TRUNC(tr.txn_date), c.name;',
''))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_content_disposition=>'ATTACHMENT'
